const { chromium } = require('/Users/yuvalt/personal/visual-renderer/bench/versus-browser/tooling/node_modules/playwright');
const url = 'file://' + __dirname + '/card.html';
const sizes = [['square',1080,1080],['landscape',1920,1080],['story',1080,1920]];

(async () => {
  const b = await chromium.launch();
  let bad = 0;
  for (const [name,w,h] of sizes) {
    const p = await b.newPage({ viewportSize:{width:w,height:h} });
    await p.goto(url); await p.evaluate(()=>document.fonts.ready);
    const r = await p.evaluate(({w,h}) => {
      const sel = ['.brand','.logo','.event','.shot','.shot img','.name','.role','.title','.when','.cta','.meta','.stage'];
      const out = {issues:[], boxes:{}};
      const els = sel.map(s=>[s,document.querySelector(s)]).filter(x=>x[1]);
      for (const [s,e] of els) {
        const b = e.getBoundingClientRect();
        out.boxes[s] = [Math.round(b.x),Math.round(b.y),Math.round(b.width),Math.round(b.height)];
        if (b.left < -0.5 || b.top < -0.5 || b.right > w+0.5 || b.bottom > h+0.5)
          out.issues.push(`OUT OF FRAME ${s} ${JSON.stringify(out.boxes[s])}`);
        if (e.scrollWidth > e.clientWidth+1 || e.scrollHeight > e.clientHeight+1)
          out.issues.push(`CLIPPED CONTENT ${s} scroll=${e.scrollWidth}x${e.scrollHeight} client=${e.clientWidth}x${e.clientHeight}`);
      }
      // circle check
      const sh = document.querySelector('.shot').getBoundingClientRect();
      if (Math.abs(sh.width-sh.height) > 0.5) out.issues.push(`SHOT NOT SQUARE ${sh.width}x${sh.height}`);
      const im = document.querySelector('.shot img').getBoundingClientRect();
      if (Math.abs(im.width-im.height) > 0.5) out.issues.push(`IMG NOT SQUARE ${im.width}x${im.height}`);
      // overlap between text/visual blocks
      const grp = ['.brand','.shot','.who','.title','.when','.cta'];
      const bx = grp.map(s=>[s,document.querySelector(s).getBoundingClientRect()]);
      for (let i=0;i<bx.length;i++) for (let j=i+1;j<bx.length;j++) {
        const [an,a]=bx[i],[bn,bb]=bx[j];
        const ox = Math.min(a.right,bb.right)-Math.max(a.left,bb.left);
        const oy = Math.min(a.bottom,bb.bottom)-Math.max(a.top,bb.top);
        if (ox > 1 && oy > 1) out.issues.push(`OVERLAP ${an} x ${bn} (${Math.round(ox)}x${Math.round(oy)}px)`);
      }
      // document scroll
      if (document.documentElement.scrollWidth > w || document.documentElement.scrollHeight > h)
        out.issues.push(`PAGE SCROLLS ${document.documentElement.scrollWidth}x${document.documentElement.scrollHeight}`);
      // font actually applied
      const fs = getComputedStyle(document.querySelector('.title')).fontFamily;
      if (!/Inter/.test(fs)) out.issues.push('FONT NOT INTER: '+fs);
      out.interLoaded = document.fonts.check('700 60px Inter');
      // title line count
      const t = document.querySelector('.title');
      const lh = parseFloat(getComputedStyle(t).lineHeight);
      out.titleLines = Math.round(t.getBoundingClientRect().height/lh);
      return out;
    }, {w,h});
    console.log(`\n=== ${name} ${w}x${h} === interLoaded=${r.interLoaded} titleLines=${r.titleLines}`);
    for (const k in r.boxes) console.log('   ', k.padEnd(10), r.boxes[k].join(', '));
    if (r.issues.length) { bad++; console.log('  !! ' + r.issues.join('\n  !! ')); }
    else console.log('   OK: no overflow / clipping / overlap');
    await p.close();
  }
  await b.close();
  console.log(bad ? `\n${bad} size(s) with issues` : '\nALL SIZES CLEAN');
})();

